using System.Collections;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AgonyHammerheadWillEffect", menuName = "Data/Battle/Effects/AgonyHammerheadWill Effect")]
public class AgonyHammerheadWillEffect : Effect
{
	[SerializeField]
	private DefaultEffectAction effectAction;

	[SerializeField]
	private float delayToApplyDoom;

	[SerializeField]
	private bool hammerheadEffect;

	protected override string GetLocalizedDescription()
	{
		return "";
	}

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetHammerheadAgonyDescription(-1);
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return GetHammerheadAgonyDescription(amount);
	}

	private string GetHammerheadAgonyDescription(int amount)
	{
		string text = "";
		string text2 = "";
		if (hammerheadEffect)
		{
			text = base.localizationManager.GetLocalizedAtTheEndOfYourTurn(withSpace: true);
			text2 = effectAction.GetActionDescription(amount).LowercaseFirst();
		}
		else
		{
			text = base.localizationManager.GetLocalizedAtTheEndOfItsTurn(withSpace: true);
			text2 = base.localizationManager.GetLocalizedEffectOwnerReceiveEffectFormatted(effectAction.Effect, amount);
		}
		return text + text2;
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		if (IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ApplyEffectCoroutine(amount, effectOwner));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			ApplyEffect(effectOwner, amount);
		}
		return amount;
	}

	private IEnumerator ApplyEffectCoroutine(int amount, GameObject effectOwner)
	{
		if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			yield return new WaitForSeconds(delayToApplyDoom / 4f);
			effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
			PlayEffectActivationSFX();
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 4f);
			yield return new WaitForSeconds(delayToApplyDoom);
			ApplyEffect(effectOwner, amount);
		}
	}

	private void ApplyEffect(GameObject effectOwner, int amount)
	{
		effectAction.CastTargetAmount(effectOwner, amount, null);
	}
}
